"""Simulated property measurements (loop step 8). ALL VALUES ARE MOCK: generated by hand-set formulas
plus a small deterministic jitter, not read from instruments. Replace measure() with real instrument
feeds later; the check in check.py does not change.

Measured: composition (at%, as an EDS-style reading), hardness (HV) and oxidation (mass gain, mg/cm2,
lower is better). The old scan fields (SEM, XRD, crack) still live in workcell.py.
"""
from __future__ import annotations

import hashlib

from .chemistry import normalize_composition, normalize_processing, parse

INSTRUMENT = "simulated (EDS, microhardness, oxidation furnace)"

# Hand-set demo deviations, keyed like workcell.MOCK_TELEMETRY. The Yellow control loses some Al on the
# additive route and oxidizes worse than its neighbors, so the measurement check has something to catch.
_CONTROL = (normalize_composition("Nb50-Ti20-Cr15-Al15"), normalize_processing("Additive/Anneal"))
_OVERRIDES = {
    _CONTROL: {"composition_shift": {"Al": -1.8, "Nb": +1.8}, "oxidation_factor": 1.8},
}


def _jitter(seed: str, scale: float) -> float:
    """Deterministic value in [-scale, +scale] from a string."""
    digest = hashlib.sha256(seed.encode()).hexdigest()
    return (int(digest[:8], 16) / 0xFFFFFFFF * 2 - 1) * scale


def expected_properties(recipe: dict[str, float], processing: str) -> tuple[float, float]:
    """The mock physics: (hardness HV, oxidation mg/cm2) before jitter."""
    route = 1.05 if normalize_processing(processing) == normalize_processing("Additive/Anneal") else 1.0
    hardness = (200 + 6.0 * recipe.get("Cr", 0) + 5.0 * recipe.get("Al", 0) + 1.2 * recipe.get("Nb", 0)) * route
    oxidation = max(0.5, 12 - 0.35 * recipe.get("Al", 0) - 0.25 * recipe.get("Cr", 0))
    return hardness, oxidation


def measure(composition: str, processing: str) -> dict:
    key = (normalize_composition(composition), normalize_processing(processing))
    seed = f"{key[0]}|{key[1]}"
    recipe = parse(composition)
    override = _OVERRIDES.get(key, {})
    shift = override.get("composition_shift", {})
    measured = {
        el: round(max(0.0, amt + shift.get(el, 0.0) + _jitter(f"{seed}:{el}", 0.5)), 1) for el, amt in recipe.items()
    }
    hardness, oxidation = expected_properties(recipe, processing)
    return {
        "mock": True,
        "instrument": INSTRUMENT,
        "composition_at_pct": measured,
        "hardness_hv": round(hardness + _jitter(f"{seed}:hv", 8), 0),
        "oxidation_mg_cm2": round(oxidation * override.get("oxidation_factor", 1.0) + _jitter(f"{seed}:ox", 0.15), 2),
    }
